import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

test('production bundle: index 使用 classic bundle，包含统一持久化与四路由且仅显式 Native Dev Mode 使用精确 loopback', () => {
  const html = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
  const bundle = readFileSync(new URL('../dist/app.bundle.js', import.meta.url), 'utf8');
  assert.match(html, /<script src="dist\/app\.bundle\.js\?v=risk-delete-confirm-contrast-20261008"><\/script>/);
  assert.match(html, /<link rel="stylesheet" href="natural-chime\.css\?v=risk-delete-confirm-contrast-20261008">/);
  assert.match(html, /<link rel="stylesheet" href="appearance\.css\?v=risk-delete-confirm-contrast-20261008">/);
  assert.equal((html.match(/\?v=risk-delete-confirm-contrast-20261008/g) || []).length, 9, '全部脚本和样式使用同一发布版本，避免新旧资源混载');
  const resources = [...html.matchAll(/(?:src|href)="([^\"]+\.(?:css|js)\?v=([^\"]+))"/g)];
  assert.equal(resources.length, 9);
  assert.ok(resources.every(([, , version]) => version === 'risk-delete-confirm-contrast-20261008'));
  assert.doesNotMatch(html, /v6-setup-hotfix-20261005/);
  assert.doesNotMatch(html, /type="module"/);
  assert.doesNotMatch(bundle, /^import\s/m);
  assert.doesNotMatch(bundle, /engine\.calculateRiskDecision/);
  assert.deepEqual([...bundle.matchAll(/https?:\/\/[^'\"\s]+/g)].map(match => match[0]), ['https://127.0.0.1:17839']);
  assert.match(bundle, /nativeMode: nativeChimeDevMode/);
  assert.match(bundle, /if \(nativeChimeDevMode\) \{/);
  assert.match(bundle, /trading-control-center:v1/);
  assert.match(bundle, /mountRiskManager/);
  assert.match(html, /#\/home/);
  assert.match(html, /#\/risk/);
  assert.match(html, /#\/chime/);
  assert.match(html, /data-route-view="chime"/);
  assert.match(bundle, /trading-control-center:natural-chime-audible-leader/);
  assert.match(bundle, /renderTextBanner/);
  assert.match(bundle, /暂无交易方向/);
  assert.match(bundle, /MTF PB/);
  assert.match(bundle, /MTF BOF（趋势走弱 1次）/);
  assert.match(bundle, /HTF BOF/);
  assert.match(bundle, /entry-signal-label">入场信号<\/span><span class="entry-signal-lines"><span>均线一侧·BB收窄·气泡攻击&amp;吸收·流动性·信号K<\/span><span>原方向拒绝\+新方向位移（COC）\+价格接受（震荡）<\/span>/);
  assert.doesNotMatch(bundle, /data-zone/);
});
